j=json.loads((H/'opus55-review.json').read_text());assert r.returncode==0 and not j['is_error'] and 'claude-opus-5-5' in j['modelUsage'];assert all(sha(F/n)==x['sha256'] for n,x in m['files'].items());print(json.dumps({'review':'complete','model':list(j['modelUsage']),'seconds':time.monotonic()-start}))
